#!/usr/bin/env python3
"""Merge user records from JSON, CSV and Parquet sources with priority."""

import json
from pathlib import Path

import pandas as pd

SOURCES = [
    ("source_a", Path("/data/source_a/users.json")),
    ("source_b", Path("/data/source_b/users.csv")),
    ("source_c", Path("/data/source_c/users.parquet")),
]

# Source-specific column names mapped to the unified schema.
FIELD_MAPS = {
    "source_a": {
        "user_id": "id",
        "name": "full_name",
        "email": "email",
        "created_date": "registration_date",
        "status": "status",
    },
    "source_b": {
        "user_id": "user_id",
        "name": "name",
        "email": "email_address",
        "created_date": "created_at",
        "status": "is_active",
    },
    "source_c": {
        "user_id": "userId",
        "name": "userName",
        "email": "email",
        "created_date": "joined",
        "status": "active",
    },
}

FIELDS = ["name", "email", "created_date", "status"]
OUTPUT_COLUMNS = ["user_id", "name", "email", "created_date", "status"]


def normalize_status(value):
    """Normalize booleans and common active flags to active/inactive strings."""
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return "active" if value == 1 else "inactive" if value == 0 else str(value)
    text = str(value).strip()
    if text.lower() in {"true", "1", "yes", "y", "active"}:
        return "active"
    if text.lower() in {"false", "0", "no", "n", "inactive"}:
        return "inactive"
    return text


def normalize_date(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    text = str(value).strip()
    if not text:
        return None
    parsed = pd.to_datetime(text, errors="coerce")
    if pd.isna(parsed):
        return text
    return parsed.strftime("%Y-%m-%d")


def clean_value(field, value):
    if value is None:
        return None
    if isinstance(value, float) and pd.isna(value):
        return None
    if isinstance(value, str) and not value.strip():
        return None
    if field == "created_date":
        return normalize_date(value)
    if field == "status":
        return normalize_status(value)
    if field in {"name", "email"}:
        return str(value).strip()
    return value


def read_source(name, path):
    if name == "source_a":
        df = pd.read_json(path)
    elif name == "source_b":
        df = pd.read_csv(path)
    else:
        df = pd.read_parquet(path)

    mapping = FIELD_MAPS[name]
    records = {}
    for _, row in df.iterrows():
        raw_id = row.get(mapping["user_id"])
        if raw_id is None or pd.isna(raw_id):
            continue
        try:
            user_id = int(raw_id)
        except (TypeError, ValueError):
            continue

        record = {}
        for field in FIELDS:
            src_col = mapping.get(field)
            record[field] = clean_value(field, row.get(src_col) if src_col else None)
        records[user_id] = record
    return records


def main():
    source_records = {name: read_source(name, path) for name, path in SOURCES}
    all_ids = sorted(set().union(*(set(records) for records in source_records.values())))

    merged_rows = []
    conflicts = []

    for user_id in all_ids:
        merged = {"user_id": user_id}

        for field in FIELDS:
            # Only sources in which this user actually has a value for the field.
            available = []
            for name, _ in SOURCES:
                if user_id in source_records[name]:
                    value = source_records[name][user_id].get(field)
                    if value is not None:
                        available.append((name, value))

            if available:
                selected = available[0][1]  # sources are in priority order
                merged[field] = selected

                values = {name: value for name, value in available}
                distinct = []
                for value in values.values():
                    if value not in distinct:
                        distinct.append(value)
                if len(distinct) > 1:
                    conflicts.append(
                        {
                            "user_id": user_id,
                            "field": field,
                            "values": values,
                            "selected": selected,
                        }
                    )
            else:
                merged[field] = None

        merged_rows.append(merged)

    merged_df = pd.DataFrame(merged_rows, columns=OUTPUT_COLUMNS)
    merged_df["user_id"] = merged_df["user_id"].astype("int64")
    for col in ["name", "email", "created_date", "status"]:
        merged_df[col] = merged_df[col].astype("string")

    merged_df.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w", encoding="utf-8") as fh:
        json.dump(report, fh, indent=2, ensure_ascii=False)
        fh.write("\n")

    print(f"Wrote {len(merged_df)} users and {len(conflicts)} conflicts")


if __name__ == "__main__":
    main()
EOF
